import { baseColors } from './base';
import dataFoundations from './dataFoundations';
import dataPrimitives from './dataPrimitives';
import { specificProperty } from './specificProperty';

export const colors = {
  ...baseColors,
  ...dataFoundations,
  ...dataPrimitives,
  specificProperty,
};
